    constructor(C _c) { c = _c; }

    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        uint cBefore = address(c).balance;
        uint tBefore = address(this).balance;

        if (depositAmount > 0) {
            c.deposit{value: depositAmount}();
        }

        c.withdrawAll();

        uint cAfter = address(c).balance;
        uint tAfter = address(this).balance;

