    }

    function run(uint amount1, uint amount2) public payable {
        require(address(this).balance >= amount1 + amount2);
        c.deposit{value: amount1}();
        uint cBal1 = address(c).balance;
        uint tBal1 = address(this).balance;
        c.deposit{value: amount2}();
        uint cBal2 = address(c).balance;
        uint tBal2 = address(this).balance;
        c.withdrawAll();
        uint cBal3 = address(c).balance;
        uint tBal3 = address(this).balance;
        c.withdrawAll();
        uint cBal4 = address(c).balance;
        uint tBal4 = address(this).balance;
        assert(cBal1 == amount1 && cBal2 == amount1 + amount2);
        assert(tBal1 == address(this).balance + amount1);
