contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount) public payable {
        // Take a deposit amount as a parameter; the test contract sends exactly that to c.
        require(address(this).balance >= depositAmount);

        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // Make a deposit, but do not withdraw it in this run; then call withdrawAll.
        // If no credit exists, withdrawAll must not move any Ether.
        if (depositAmount > 0) {
            c.deposit{value: depositAmount}();
            beforeC = address(c).balance;
            beforeThis = address(this).balance;
        }

        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!reverted && address(c).balance == beforeC && address(this).balance + depositAmount == beforeThis);
    }

    receive() external payable {}
}

